const ctx = canvas.getContext('2d');
canvas.width = canvas.offsetWidth;
canvas.height = canvas.offsetHeight;

let phase = 0;
function drawWave() {
  ctx.fillStyle = 'rgba(10, 11, 16, 0.3)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.beginPath();
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#06b6d4';
  ctx.shadowBlur = 15;
  ctx.shadowColor = '#06b6d4';

  const sliceWidth = canvas.width / 100;
  let x = 0;

  for (let i = 0; i < 100; i++) {
    const v = Math.sin(i * 0.15 + phase) * 40 + Math.sin(i * 0.3 - phase * 1.5) * 20;
    const y = canvas.height / 2 + v;

    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    x += sliceWidth;
  }

  ctx.stroke();
  phase += 0.05;
  requestAnimationFrame(drawWave);
}
drawWave();`}},xA=()=>{const[r,e]=I.useState("taskManager"),[n,i]=I.useState("html"),[l,u]=I.useState(aa.taskManager.html),[d,f]=I.useState(aa.taskManager.js),[g,m]=I.useState(""),[C,v]=I.useState(!1),A=I.useRef(null);I.useEffect(()=>{(()=>{try{const H=localStorage.getItem("argus-codestudio-active-project");if(H){const W=JSON.parse(H);W.html&&u(W.html),W.js&&f(W.js),W.templateKey&&e(W.templateKey)}}catch{}})();const U=H=>{H.detail&&(H.detail.html&&u(H.detail.html),H.detail.js&&f(H.detail.js),H.detail.templateKey&&e(H.detail.templateKey))};return window.addEventListener("argus:codestudio-load-code",U),()=>window.removeEventListener("argus:codestudio-load-code",U)},[]);const N=()=>{if(!A.current)return;const O=`
